using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD intrinsics (AVX2 / SSE / AdvSimd) for high throughput on large arrays.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (values.Length == 1)
            return (values[0], values[0]);

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;

        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count * 2)
        {
            return FindMinMax256(ref start, length);
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count * 2)
        {
            return FindMinMax128(ref start, length);
        }

        return FindMinMaxScalar(ref start, length);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax256(ref float start, int length)
    {
        int vectorSize = Vector256<float>.Count; // 8
        int i = 0;

        var vMin = Vector256.LoadUnsafe(ref start);
        var vMax = vMin;
        i += vectorSize;

        // Process two vectors per iteration to improve ILP
        int limit = length - vectorSize * 2 + 1;
        for (; i < limit; i += vectorSize * 2)
        {
            var v0 = Vector256.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector256.LoadUnsafe(ref start, (nuint)(i + vectorSize));
            vMin = Vector256.Min(vMin, Vector256.Min(v0, v1));
            vMax = Vector256.Max(vMax, Vector256.Max(v0, v1));
        }

        // Handle remaining full vectors
        for (; i <= length - vectorSize; i += vectorSize)
        {
            var v = Vector256.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector256.Min(vMin, v);
            vMax = Vector256.Max(vMax, v);
        }

        // Reduce 256-bit to scalar
        var minLo = vMin.GetLower();
        var minHi = vMin.GetUpper();
        var maxLo = vMax.GetLower();
        var maxHi = vMax.GetUpper();
        var min128 = Vector128.Min(minLo, minHi);
        var max128 = Vector128.Max(maxLo, maxHi);

        float min = HorizontalMin(min128);
        float max = HorizontalMax(max128);

        // Scalar tail
        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax128(ref float start, int length)
    {
        int vectorSize = Vector128<float>.Count; // 4
        int i = 0;

        var vMin = Vector128.LoadUnsafe(ref start);
        var vMax = vMin;
        i += vectorSize;

        int limit = length - vectorSize * 2 + 1;
        for (; i < limit; i += vectorSize * 2)
        {
            var v0 = Vector128.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector128.LoadUnsafe(ref start, (nuint)(i + vectorSize));
            vMin = Vector128.Min(vMin, Vector128.Min(v0, v1));
            vMax = Vector128.Max(vMax, Vector128.Max(v0, v1));
        }

        for (; i <= length - vectorSize; i += vectorSize)
        {
            var v = Vector128.LoadUnsafe(ref start, (nuint)i);
            vMin = Vector128.Min(vMin, v);
            vMax = Vector128.Max(vMax, v);
        }

        float min = HorizontalMin(vMin);
        float max = HorizontalMax(vMax);

        for (; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMaxScalar(ref float start, int length)
    {
        float min = start;
        float max = start;
        for (int i = 1; i < length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }
        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin(Vector128<float> v)
    {
        // Reduce 4 floats to 1 minimum via shuffle + min
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Min(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Min(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax(Vector128<float> v)
    {
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Max(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Max(v, shuf);
        return v.ToScalar();
    }
}

